let currentState = { mode: null, categoryKey: null, queue: [], currentIndex: 0, displayName: "" };
const STORAGE_KEY_PROGRESS = 'kpss_cografya_progress_v9';
const STORAGE_KEY_SIZE = 'kpss_map_size_v1';
const STORAGE_KEY_NOTES = 'kpss_cografya_notes_v2';
const STORAGE_KEY_LAST_ACTIVE = 'kpss_last_active_v1';

let categoryListEl, questionTitleEl, answerMapEl, answerSectionEl, baseMapEl, canvas, ctx, sidebar, gameAreaEl, resizableContainer;
let drawingState = { isDrawing: false, tool: 'brush', color: '#007AFF', lineWidth: 4, startX: 0, startY: 0, snapshot: null };
let history = [];
let historyStep = -1;

// --- YENİ EKLENEN BAŞLANGIÇ SİSTEMİ (LİSTE KURTARICI) ---
window.appInitialized = false;

window.onload = () => {
    // 1. Python bağlandıysa (Masaüstü App) hafızayı fiziksel dosyadan çek
    if (window.pywebview) {
        syncDataFromPython();
    } else {
        // Eğer yüklenmesi zaman alırsa diye event listener ekliyoruz
        window.addEventListener('pywebviewready', syncDataFromPython);

        // Tarayıcıdaysak (Python yoksa) 0.5sn bekle ve direkt başlat
        setTimeout(() => {
            if (!window.pywebview) initializeAppUI();
        }, 500);
    }
};

async function syncDataFromPython() {
    try {
        let dataStr = await window.pywebview.api.load_app_data();
        if (dataStr) {
            let data = JSON.parse(dataStr);
            // Python'daki listeleri JS hafızasına geri yükle
            if (data.progress) localStorage.setItem(STORAGE_KEY_PROGRESS, data.progress);
            if (data.lastActive) localStorage.setItem(STORAGE_KEY_LAST_ACTIVE, data.lastActive);
        }
    } catch (e) {
        console.error("Fiziksel hafıza okunamadı.");
    }
    initializeAppUI(); // Hafıza doldu, şimdi arayüzü çiz
}

function initializeAppUI() {
    if (window.appInitialized) return;
    window.appInitialized = true;

    categoryListEl = document.getElementById('category-list');
    questionTitleEl = document.getElementById('question-title');
    answerMapEl = document.getElementById('answer-map');
    answerSectionEl = document.getElementById('answer-section');
    baseMapEl = document.getElementById('base-map');
    canvas = document.getElementById('draw-canvas');
    ctx = canvas.getContext('2d');
    sidebar = document.getElementById('sidebar');
    gameAreaEl = document.getElementById('game-area');
    resizableContainer = document.getElementById('resizable-container');

    initSidebar();
    loadMapSize();
    setupCanvasEvents();
    setupUIEvents();
    setupToolEvents();
    setupSearch();
    renderSavedLists(); // Listeleri ekrana bas

    // AUTO-RESUME: Son kalınan yeri yükle
    let lastActive = localStorage.getItem(STORAGE_KEY_LAST_ACTIVE);
    if (lastActive) {
        let saved = getSavedProgress(lastActive);
        if (saved && saved.queue && saved.queue.length > 0) {
            currentState = saved;
            loadQuestion();
        }
    }
}

// --- FİZİKSEL KAYIT MOTORU ---
async function saveProgress() {
    try {
        if (!currentState.categoryKey) return;

        let allProgress = JSON.parse(localStorage.getItem(STORAGE_KEY_PROGRESS)) || {};
        allProgress[currentState.categoryKey] = currentState;

        let progressStr = JSON.stringify(allProgress);
        localStorage.setItem(STORAGE_KEY_PROGRESS, progressStr);

        let lastActive = currentState.categoryKey;
        localStorage.setItem(STORAGE_KEY_LAST_ACTIVE, lastActive);

        // ÖNEMLİ: Listeyi fiziksel Python (.json) hafızasına gönder!
        if (window.pywebview) {
            let payload = JSON.stringify({ progress: progressStr, lastActive: lastActive });
            await window.pywebview.api.save_app_data(payload);
        }

        renderSavedLists();
    } catch (e) { console.error(e); }
}


// --- ARAMA SİSTEMİ ---
function setupSearch() {
    const searchInput = document.getElementById('map-search');
    const resultsDiv = document.getElementById('search-results');
    searchInput.oninput = (e) => {
        const term = e.target.value.toLocaleLowerCase('tr').trim();
        if (term.length < 2) { resultsDiv.classList.add('hidden'); return; }
        let matches = [];
        Object.keys(DATA).forEach(cat => {
            DATA[cat].files.forEach(file => {
                const title = cleanFileName(file);
                if (title.toLocaleLowerCase('tr').includes(term)) matches.push({ category: cat, fileName: file, title: title, path: DATA[cat].path + file });
            });
        });
        renderSearchResults(matches);
    };
    document.addEventListener('click', (e) => { if (!searchInput.contains(e.target) && !resultsDiv.contains(e.target)) resultsDiv.classList.add('hidden'); });
}

function renderSearchResults(matches) {
    const resultsDiv = document.getElementById('search-results');
    resultsDiv.innerHTML = "";
    if (matches.length === 0) {
        resultsDiv.innerHTML = '<div class="search-result-item">Sonuç bulunamadı...</div>';
        resultsDiv.classList.remove('hidden');
        return;
    }
    matches.forEach(match => {
        const item = document.createElement('div');
        item.className = 'search-result-item';
        item.innerHTML = `<strong>${match.title}</strong><small>${match.category}</small>`;
        item.onclick = () => { selectSearchQuestion(match); document.getElementById('map-search').value = ""; resultsDiv.classList.add('hidden'); };
        resultsDiv.appendChild(item);
    });
    resultsDiv.classList.remove('hidden');
}

function selectSearchQuestion(match) {
    currentState = { mode: 'search', categoryKey: 'search_mode', displayName: "Arama Sonucu", queue: [{ path: match.path, title: match.title, category: match.category }], currentIndex: 0 };
    closeSidebarOnMobile();
    loadQuestion();
}

// --- DOSYA VE NOT YÖNETİMİ ---
async function loadPermanentNote(category, title) {
    const noteArea = document.getElementById('permanent-note');
    const status = document.getElementById('save-status');
    let noteContent = "";

    if (window.pywebview) {
        try { noteContent = await window.pywebview.api.load_note(category, title); } catch (e) { }
    }
    if (!noteContent) {
        const savedNotes = JSON.parse(localStorage.getItem(STORAGE_KEY_NOTES)) || {};
        noteContent = savedNotes[`${category}_${title}`] || "";
    }
    noteArea.value = noteContent;
    status.classList.add('hidden');
}

async function saveCurrentNote() {
    const currentQ = currentState.queue[currentState.currentIndex];
    const noteContent = document.getElementById('permanent-note').value;
    const status = document.getElementById('save-status');

    const savedNotes = JSON.parse(localStorage.getItem(STORAGE_KEY_NOTES)) || {};
    const key = `${currentQ.category}_${currentQ.title}`;
    if (noteContent.trim() === "") delete savedNotes[key];
    else savedNotes[key] = noteContent;
    localStorage.setItem(STORAGE_KEY_NOTES, JSON.stringify(savedNotes));

    if (window.pywebview) {
        try { await window.pywebview.api.save_note(currentQ.category, currentQ.title, noteContent); } catch (e) { }
    }

    status.classList.remove('hidden');
    setTimeout(() => status.classList.add('hidden'), 2000);
}

async function loadAttachments(category, title) {
    const listEl = document.getElementById('attachment-list');
    if (!listEl) return;
    listEl.innerHTML = '';

    if (window.pywebview) {
        const files = await window.pywebview.api.get_attachments(category, title);
        if (files && files.length > 0) {
            files.forEach(file => {
                const div = document.createElement('div');
                div.className = 'attachment-item';
                div.innerHTML = `<span>📄 ${file}</span> <button onclick="openAttachment('${category}', '${title}', '${file}')">Aç</button>`;
                listEl.appendChild(div);
            });
        } else {
            listEl.innerHTML = '<span class="empty-attach">Henüz ekli dosya yok.</span>';
        }
    } else {
        listEl.innerHTML = '<span class="empty-attach">Dosya ekleme özelliği masaüstü uygulamasında çalışır.</span>';
    }
}

window.attachFile = async function () {
    if (!window.pywebview) return alert("Bu özellik masaüstü uygulamasında geçerlidir.");
    const currentQ = currentState.queue[currentState.currentIndex];
    const result = await window.pywebview.api.attach_file(currentQ.category, currentQ.title);
    if (result) loadAttachments(currentQ.category, currentQ.title);
};

window.openAttachment = async function (category, title, filename) {
    if (window.pywebview) await window.pywebview.api.open_attachment(category, title, filename);
};


// --- TEMEL AKIŞ VE LİSTE YÖNETİMİ ---
function initSidebar() {
    categoryListEl.innerHTML = "";
    Object.keys(DATA).forEach(catName => {
        const div = document.createElement('div');
        div.className = 'category-item';
        div.innerHTML = `<input type="checkbox" class="cat-checkbox" value="${catName}"><span class="category-name">${catName}</span><span class="badge" style="font-size:0.8em; color:var(--text-muted);">(${DATA[catName].files.length})</span>`;
        div.querySelector('.category-name').onclick = () => startSingleCategory(catName);
        div.querySelector('input').onchange = updateMixButton;
        categoryListEl.appendChild(div);
    });
}

function startSingleCategory(catName) {
    let saved = getSavedProgress(catName);
    if (saved && saved.queue.length > 0) currentState = saved;
    else {
        const files = DATA[catName].files.map(f => ({ path: DATA[catName].path + f, title: cleanFileName(f), category: catName }));
        currentState = { mode: 'single', categoryKey: catName, displayName: catName, queue: shuffleArray(files), currentIndex: 0 };
    }
    closeSidebarOnMobile();
    loadQuestion();
}

// KAYITLI LİSTELERİ RENDER ET
function renderSavedLists() {
    const container = document.getElementById('saved-lists');
    if (!container) return;
    container.innerHTML = "";

    let allProgress = JSON.parse(localStorage.getItem(STORAGE_KEY_PROGRESS)) || {};
    let hasCustom = false;

    Object.keys(allProgress).forEach(key => {
        if (key.startsWith('custom_mix_')) {
            hasCustom = true;
            const state = allProgress[key];
            const div = document.createElement('div');
            div.className = 'category-item';
            div.style.flexDirection = 'column';
            div.style.alignItems = 'flex-start';
            div.style.padding = '10px';
            div.style.border = '1px solid var(--border-color)';
            div.style.marginBottom = '8px';

            const progressText = `${state.currentIndex} / ${state.queue.length}`;

            // Eğer liste tamamlanmışsa yeşil renk yapalım
            const isDone = state.currentIndex >= state.queue.length - 1;
            const statusColor = isDone ? 'var(--success)' : 'var(--accent)';

            div.innerHTML = `
                <div style="display:flex; justify-content:space-between; width:100%; margin-bottom:5px;">
                    <strong style="color:var(--text-main); font-size:0.95rem; cursor:pointer;" onclick="resumeList('${key}')">${state.displayName}</strong>
                    <button onclick="deleteList('${key}', event)" title="Listeyi Sil" style="background:none; border:none; color:var(--danger); cursor:pointer; font-size:1.1rem; padding:0;">🗑️</button>
                </div>
                <div style="width:100%; display:flex; justify-content:space-between; align-items:center; cursor:pointer;" onclick="resumeList('${key}')">
                    <small style="color:var(--text-muted);">Kaldığın yer:</small>
                    <small style="color:white; background:${statusColor}; padding:2px 8px; border-radius:10px; font-weight:bold;">${progressText}</small>
                </div>
            `;
            container.appendChild(div);
        }
    });

    if (!hasCustom) {
        container.innerHTML = '<span style="font-size:0.85rem; color:var(--text-muted); padding:5px 10px; display:block; text-align:center;">Henüz kayıtlı özel listeniz yok. Karıştır butonunu kullanın.</span>';
    }
}

window.resumeList = function (key) {
    let saved = getSavedProgress(key);
    if (saved) {
        currentState = saved;
        closeSidebarOnMobile();
        loadQuestion();
    }
};

window.deleteList = async function (key, event) {
    event.stopPropagation();
    if (confirm("Bu çalışma listesini silmek istediğinize emin misiniz? (Aldığınız notlar silinmez!)")) {
        let allProgress = JSON.parse(localStorage.getItem(STORAGE_KEY_PROGRESS)) || {};
        delete allProgress[key];
        let progressStr = JSON.stringify(allProgress);
        localStorage.setItem(STORAGE_KEY_PROGRESS, progressStr);

        // Sildiğimizde de Python (.json) tarafını güncelliyoruz
        if (window.pywebview) {
            let lastActive = localStorage.getItem(STORAGE_KEY_LAST_ACTIVE);
            if (lastActive === key) lastActive = null;
            let payload = JSON.stringify({ progress: progressStr, lastActive: lastActive });
            await window.pywebview.api.save_app_data(payload);
        }

        // Eğer silinen liste o an ekranda açıksa ekranı temizle
        if (currentState && currentState.categoryKey === key) {
            currentState = { mode: null, categoryKey: null, queue: [], currentIndex: 0, displayName: "" };
            document.getElementById('question-title').innerText = "Başlamak için soldan bir konu seçin.";
            answerSectionEl.classList.add('hidden');
            document.getElementById('temp-note-section').style.display = 'none';
            document.getElementById('base-map').src = "images/karışık/bos_harita.jpg";
            document.getElementById('current-category-name').innerText = "Kategori Seçiniz";
            document.getElementById('progress-counter').innerText = "0 / 0";
            document.getElementById('btn-show-answer').style.display = 'none';
            document.getElementById('btn-next').style.display = 'none';
            document.getElementById('btn-prev').style.display = 'none';
            ctx.clearRect(0, 0, canvas.width, canvas.height);
        }
        renderSavedLists();
    }
};

function loadQuestion() {
    if (!currentState.queue || currentState.queue.length === 0) return;
    if (currentState.currentIndex >= currentState.queue.length) {
        alert("Harika! Bu listeyi bitirdiniz. Başa dönülüyor...");
        currentState.currentIndex = 0;
        currentState.queue = shuffleArray(currentState.queue);
    }
    const currentQ = currentState.queue[currentState.currentIndex];
    document.getElementById('current-category-name').innerText = currentState.displayName;
    document.getElementById('progress-counter').innerText = `${currentState.currentIndex + 1} / ${currentState.queue.length}`;
    questionTitleEl.innerText = currentQ.title;

    answerSectionEl.classList.add('hidden');
    answerMapEl.src = "";

    const tempNoteSec = document.getElementById('temp-note-section');
    if (tempNoteSec) {
        document.getElementById('temp-note').value = "";
        tempNoteSec.style.display = 'flex';
    }

    loadPermanentNote(currentQ.category, currentQ.title);
    loadAttachments(currentQ.category, currentQ.title);

    const btnPrev = document.getElementById('btn-prev');
    const btnNext = document.getElementById('btn-next');
    const btnShow = document.getElementById('btn-show-answer');

    btnShow.style.display = 'inline-block';
    btnNext.style.display = 'none';
    btnPrev.style.display = (currentState.currentIndex > 0) ? 'inline-block' : 'none';

    history = []; historyStep = -1;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    setTimeout(() => { resizeCanvas(); saveHistory(); }, 50);
    saveProgress();
}

window.showAnswer = function () {
    const currentQ = currentState.queue[currentState.currentIndex];
    answerMapEl.src = currentQ.path;
    answerSectionEl.classList.remove('hidden');
    document.getElementById('btn-show-answer').style.display = 'none';
    document.getElementById('btn-next').style.display = 'inline-block';
    setTimeout(() => { answerSectionEl.scrollIntoView({ behavior: 'smooth' }); }, 100);
};

window.nextQuestion = function () {
    if (!answerSectionEl.classList.contains('hidden')) saveCurrentNote();
    currentState.currentIndex++;
    loadQuestion();
    gameAreaEl.scrollTo({ top: 0, behavior: 'smooth' });
};

window.prevQuestion = function () {
    if (!answerSectionEl.classList.contains('hidden')) saveCurrentNote();
    if (currentState.currentIndex > 0) {
        currentState.currentIndex--;
        loadQuestion();
        gameAreaEl.scrollTo({ top: 0, behavior: 'smooth' });
    }
};

function cleanFileName(filename) { return filename.replace(/\.(jpg|jpeg|png)$/i, '').replace(/_/g, ' '); }
function shuffleArray(array) {
    let newArr = [...array];
    for (let i = newArr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
    }
    return newArr;
}
function getSavedProgress(key) { try { return JSON.parse(localStorage.getItem(STORAGE_KEY_PROGRESS))[key]; } catch (e) { return null; } }

function applyMapSize(sizePercent) {
    resizableContainer.style.width = sizePercent + "%";
    answerSectionEl.style.width = sizePercent + "%";
    localStorage.setItem(STORAGE_KEY_SIZE, sizePercent);
}
window.changeMapSize = (delta) => {
    let currentWidth = parseInt(resizableContainer.style.width) || 100;
    let newWidth = Math.min(Math.max(currentWidth + delta, 30), 200);
    applyMapSize(newWidth);
};
window.resetMapSize = () => applyMapSize(100);
function loadMapSize() { let savedSize = localStorage.getItem(STORAGE_KEY_SIZE); applyMapSize(savedSize ? parseInt(savedSize) : 100); }

function setupCanvasEvents() {
    if (baseMapEl.complete) resizeCanvas(); else baseMapEl.onload = resizeCanvas;
    window.onresize = resizeCanvas;
    canvas.onmousedown = startDraw; canvas.onmousemove = draw; canvas.onmouseup = stopDraw; canvas.onmouseout = stopDraw;
    canvas.ontouchstart = startDraw; canvas.ontouchmove = draw; canvas.ontouchend = stopDraw;
}
function resizeCanvas() {
    canvas.width = baseMapEl.clientWidth; canvas.height = baseMapEl.clientHeight;
    if (history.length > 0 && historyStep >= 0) {
        let img = new Image(); img.src = history[historyStep];
        img.onload = () => ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    }
    ctx.lineCap = "round"; ctx.lineJoin = "round";
}
function setupToolEvents() {
    document.getElementById('color-picker').onchange = (e) => drawingState.color = e.target.value;
    document.getElementById('line-width').oninput = (e) => drawingState.lineWidth = e.target.value;
}
window.setTool = (toolName) => {
    drawingState.tool = toolName;
    document.querySelectorAll('.tool-btn').forEach(btn => btn.classList.remove('active'));
    document.getElementById('btn-' + toolName).classList.add('active');
};
function saveHistory() {
    historyStep++;
    if (historyStep < history.length) history.length = historyStep;
    history.push(canvas.toDataURL());
}
window.undo = () => { if (historyStep > 0) { historyStep--; redrawHistory(); } };
window.redo = () => { if (historyStep < history.length - 1) { historyStep++; redrawHistory(); } };
function redrawHistory() {
    let img = new Image(); img.src = history[historyStep];
    img.onload = () => { ctx.clearRect(0, 0, canvas.width, canvas.height); ctx.drawImage(img, 0, 0); };
}
window.clearCanvas = () => { ctx.clearRect(0, 0, canvas.width, canvas.height); saveHistory(); };

const getPos = (e) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width, scaleY = canvas.height / rect.height;
    const clientX = e.touches ? e.touches[0].clientX : e.clientX, clientY = e.touches ? e.touches[0].clientY : e.clientY;
    return { x: (clientX - rect.left) * scaleX, y: (clientY - rect.top) * scaleY };
};
const startDraw = (e) => {
    if (e.cancelable) e.preventDefault();
    drawingState.isDrawing = true;
    const pos = getPos(e);
    drawingState.startX = pos.x; drawingState.startY = pos.y;
    drawingState.snapshot = ctx.getImageData(0, 0, canvas.width, canvas.height);
    ctx.beginPath(); ctx.lineWidth = drawingState.lineWidth; ctx.strokeStyle = drawingState.color;
    if (drawingState.tool === 'brush') ctx.moveTo(pos.x, pos.y);
};
const draw = (e) => {
    if (!drawingState.isDrawing) return;
    if (e.cancelable) e.preventDefault();
    const pos = getPos(e);
    if (drawingState.tool === 'brush') { ctx.lineTo(pos.x, pos.y); ctx.stroke(); }
    else {
        ctx.putImageData(drawingState.snapshot, 0, 0); ctx.beginPath();
        if (drawingState.tool === 'line') { ctx.moveTo(drawingState.startX, drawingState.startY); ctx.lineTo(pos.x, pos.y); ctx.stroke(); }
        else if (drawingState.tool === 'rect') { ctx.strokeRect(drawingState.startX, drawingState.startY, pos.x - drawingState.startX, pos.y - drawingState.startY); }
        else if (drawingState.tool === 'circle') {
            let r = Math.sqrt(Math.pow(pos.x - drawingState.startX, 2) + Math.pow(pos.y - drawingState.startY, 2));
            ctx.arc(drawingState.startX, drawingState.startY, r, 0, 2 * Math.PI); ctx.stroke();
        }
    }
};
const stopDraw = () => { if (drawingState.isDrawing) { drawingState.isDrawing = false; saveHistory(); } };

function updateMixButton() {
    const checked = document.querySelectorAll('.cat-checkbox:checked');
    const btn = document.getElementById('btn-mix-selected');
    btn.disabled = checked.length === 0;
    btn.innerText = checked.length > 0 ? `Seçilenleri Karıştır (${checked.length})` : "Seçilenleri Karıştır";
}

window.startAllMix = () => {
    let pool = [];
    Object.keys(DATA).forEach(cat => DATA[cat].files.forEach(f => pool.push({ path: DATA[cat].path + f, title: cleanFileName(f), category: cat })));

    let listName = prompt("Bu tam karışık listeye bir isim verin (Örn: Genel Deneme 1):", "Tüm Konular Karışık");
    if (!listName) return;

    let storageKey = "custom_mix_" + new Date().getTime();
    startMixedMode(storageKey, pool, listName);
};

function startMixedMode(storageKey, pool, displayName) {
    let saved = getSavedProgress(storageKey);
    currentState = (saved && saved.queue.length > 0) ? saved : { mode: 'mixed', categoryKey: storageKey, displayName: displayName, queue: shuffleArray(pool), currentIndex: 0 };
    closeSidebarOnMobile();
    loadQuestion();
}

function setupUIEvents() {
    const toggleBtn = document.getElementById('toggle-menu'), sidebar = document.getElementById('sidebar');
    if (toggleBtn) {
        toggleBtn.onclick = () => {
            if (window.innerWidth > 768) { sidebar.classList.toggle('collapsed'); setTimeout(resizeCanvas, 310); }
            else sidebar.classList.toggle('open');
        };
    }

    document.getElementById('btn-mix-selected').onclick = () => {
        const checked = document.querySelectorAll('.cat-checkbox:checked');
        let pool = [];
        checked.forEach(cb => {
            DATA[cb.value].files.forEach(f => pool.push({ path: DATA[cb.value].path + f, title: cleanFileName(f) + ` (${cb.value})`, category: cb.value }));
        });

        let listName = prompt("Bu çalışma listesi için bir isim belirleyin (Örn: Sınav Öncesi Son Tekrar):", "Yeni Karışık Liste");
        if (!listName) return;

        let storageKey = "custom_mix_" + new Date().getTime();
        startMixedMode(storageKey, pool, listName);
    };

    document.getElementById('btn-mix-all').onclick = window.startAllMix;
    document.getElementById('btn-reset-progress').onclick = () => { if (confirm("Tüm ilerlemeleriniz (Kayıtlı listeler ve kaldığınız yerler) sıfırlansın mı? (Fiziksel notlarınız silinmez)")) { localStorage.clear(); location.reload(); } };
    document.getElementById('btn-help').onclick = () => document.getElementById('help-modal').classList.remove('hidden');
    document.querySelector('.close-modal').onclick = () => document.getElementById('help-modal').classList.add('hidden');
}
function closeSidebarOnMobile() { if (window.innerWidth <= 768) document.getElementById('sidebar').classList.remove('open'); }